	allegiance = "Die Atal'ai",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Atal'alarion ist der {link:the-night-watch}Wächter{/link} des Götzen, der am Grund des versunkenen Tempels liegt. Um eine runde Halle stehen sechs Balkone, jeder mit einer Schlangenstatue an seinem Rand. Am Fuß der Halle wartet ein Altar Hakkars. Wer die Statuen in der falschen Weise weckt, wird von Fallen niedergeworfen. Wer die richtige Reihenfolge findet, ruft den Wächter herbei. Er ist ein ungeschlachter Rohling, und er verspricht, sich an den Knochen der Eindringlinge gütlich zu tun.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Atal'alarion hütet den Schatz der Atal'ai. Der Goblingelehrte {link:marvon-rivetseeker}Marvon Rivetseeker{/link} war der erste Außenstehende, der den Kreis fand, und es kostete ihn beinahe das Leben.]=],
		},
	},
	chapters = {
		{
			title = "Das Geheimnis des Kreises",
			hint = [=[Helft dem Goblingelehrten in Tanaris, den Altar zu entriegeln.]=],
			text = [=[{link:marvon-rivetseeker}Marvon{/link} setzte eine steinerne Marke in den Altar Hakkars ein, und damit weckte er ein Muster aus Lichtern. Als die Statuen in der Reihenfolge berührt wurden, die die Lichter enthüllten, erhob sich der {link:the-night-watch}Wächter{/link}. Hinter dem Auge des Götzen lag der Schatz der Atal'ai.]=],
		},
	},
	mentions = {
		{ text = "In die Tiefe" },
		{ text = "Eine bessere Zutat" },
	},
	bonds = {
		{ id = "hakkar", name = "Hakkar", note = "der Gott, dessen Altar er bewacht" },
	},
})

